// CPR/First Aid Practice Test 5. Original questions written for Valus from the HOSA 2026–27 test plan,
// slightly harder than the sample items and covering different situations from Practice Tests 1–4.
import {q, mix} from './q.js';
const AHA_BLS='AHA Basic Life Support', AHA_FA='AHA Heartsaver First Aid', ARC_BLS='ARC Basic Life Support', ARC_FA='ARC First Aid/CPR/AED', DHO='Simmers, DHO: Health Science';
const GEN='General Concepts', CPR='BLS/CPR for Adults, Children and Infants', AED='AED for Adults, Children and Infants', ADV='CPR with Advanced Airway', RB='Mouth-to-Mouth/Rescue Breathing', CH='Relief of Choking';
const BASIC='Basic', MED='Medical Emergencies', INJ='Injury Emergencies', ENV='Environmental Emergencies';

export default {
 id:'cpr-first-aid-5',
 event:'CPR/First Aid',
 title:'Practice Test 5',
 subtitle:'Full-length Round One simulation',
 minutes:60,
 sources:'AHA and American Red Cross BLS and First Aid, and DHO: Health Science',
 plan:[
  {area:'Basic Life Support',weight:40,topics:[GEN,CPR,AED,ADV,RB,CH]},
  {area:'First Aid',weight:60,topics:[BASIC,MED,INJ,ENV]}
 ],
 questions:mix([
  q(GEN,'How much can immediate bystander CPR improve a person’s chance of surviving sudden cardiac arrest?','It can double or triple the chance of survival',['It makes almost no difference to survival','It helps only if an AED is used first','It improves survival only in children'],'A','Immediate high-quality CPR keeps blood flowing to the brain and heart until defibrillation and can double or triple survival from cardiac arrest.',AHA_BLS),
  q(GEN,'A lay rescuer finds an adult who is unresponsive and not breathing normally. Should the rescuer check for a pulse first?','No; lay rescuers start CPR without a pulse check',['Yes; for a full minute at the wrist','Yes; at the neck before calling 911','No; they should wait for a pulse to return'],'B','Pulse checks are unreliable for lay rescuers, so an unresponsive person who is not breathing normally should get CPR right away.',AHA_BLS),
  q(GEN,'A caller tells the 911 dispatcher they do not know CPR. What should the dispatcher do?','Coach the caller through Hands-Only CPR by phone',['Tell the caller to wait for EMS to arrive','Ask the caller to find a trained person first','Have the caller check the pulse every minute'],'C','Telecommunicator (dispatcher-assisted) CPR coaches untrained callers to recognize arrest and push hard and fast until help arrives.',AHA_BLS),
  q(GEN,'A lone rescuer has been doing CPR for 20 minutes in a remote area. When may they stop?','When too exhausted to continue',['Whenever the person’s skin turns pale','After the first 5 minutes of CPR','As soon as a bystander starts watching'],'D','CPR continues until the person shows signs of life, an AED or trained help takes over, the scene becomes unsafe or the rescuer is too exhausted to go on.',ARC_BLS),
  q(CPR,'Where does a healthcare provider check for a pulse in an unresponsive adult?','The carotid artery on the side of the neck',['The radial artery on the thumb side of the wrist','The brachial artery inside the upper arm','The femoral artery in the groin only'],'A','For adults and children, providers check the carotid pulse (the femoral is an option in children) for at least 5 but no more than 10 seconds.',AHA_BLS),
  q(CPR,'During CPR, what is the goal for any pause in chest compressions, such as for breaths or rhythm analysis?','Less than 10 seconds',['About 30 seconds','Up to 1 minute','No limit if needed'],'B','Every pause stops blood flow to the brain and heart, so interruptions should be kept under 10 seconds.',AHA_BLS),
  q(CPR,'For BLS purposes, when should a teenager be treated with adult CPR techniques?','Once they show signs of puberty',['Only after turning 18 years old','Only if they weigh over 100 lb','Only if they are in high school'],'C','For BLS, “child” means 1 year old to puberty; signs such as breast development in girls or underarm hair in boys mean adult techniques are used.',AHA_BLS),
  q(CPR,'Which method opens the airway of an unresponsive person with no suspected spine injury?','Head tilt–chin lift',['Jaw-thrust only','Abdominal thrusts','Back blows'],'D','The head tilt–chin lift lifts the tongue off the back of the throat; the jaw thrust is used when a spinal injury is suspected.',AHA_BLS),
  q(CPR,'A rescuer keeps time to the beat of a popular song while doing compressions. Why is this useful?','It helps keep the rate at 100–120 per minute',['It lets the rescuer skip counting breaths','It sets the depth for compressions','It replaces the need to check pulse'],'A','Songs with about 100–120 beats per minute, such as “Stayin’ Alive,” help rescuers keep the recommended compression rate.',AHA_BLS),
  q(CPR,'Where are chest compressions given on an infant?','In the center of the chest, just below the nipple line',['On the upper third of the breastbone, near the neck','Over the left side of the chest, near the arm','On the lower abdomen, just below the ribs'],'B','Infant compressions are given in the center of the chest just below the nipple line, on the lower half of the breastbone.',AHA_BLS),
  q(AED,'The AED says “No shock advised” for a person who is still unresponsive and not breathing. What should the rescuer do?','Resume CPR immediately, starting with compressions',['Turn off the AED and wait for EMS to arrive','Remove the pads and place them in new spots','Press the shock button anyway to be safe'],'C','“No shock advised” means the rhythm is not shockable, not that the person is fine; continue CPR until the AED reanalyzes about 2 minutes later.',AHA_BLS),
  q(AED,'An adult collapses in a moving ambulance or car, and an AED is available. What should happen before analysis?','Stop the vehicle so motion does not disrupt analysis',['Analyze while driving to save time','Place the pads on the person’s back only','Wait to use the AED until reaching the hospital'],'D','Vehicle movement can interfere with rhythm analysis, so the vehicle should be stopped before the AED analyzes.',ARC_BLS),
  q(AED,'A person in cardiac arrest is lying on snow. Can the AED be used?','Yes, after drying the chest and moving to a dry spot if possible',['No, an AED can never be used outdoors','No, snow makes any shock too dangerous for rescuers nearby','Yes, but only on the person’s back'],'A','An AED can be used on snow or ice; dry the chest so the pads stick, and avoid standing water that could carry current.',ARC_BLS),
  q(AED,'A woman in cardiac arrest wears a necklace and an underwire bra. What is the key concern for pad placement?','Pads must not be placed over metal; move jewelry or wire away',['The shock will not work through any clothing','The AED cannot be used on anyone who is wearing jewelry','The pads must be placed on the arms instead'],'B','Pads go on bare skin and should not touch metal; move necklaces aside and remove the bra if its wire lies under a pad site, without delaying the shock.',ARC_BLS),
  q(ADV,'Two rescuers give bag-mask ventilation. What is the best way to divide the task?','One seals the mask with both hands; the other squeezes the bag',['One squeezes the bag; the other checks the pulse','Both squeeze the bag together at the same time for larger breaths','One holds the bag; the other gives back blows'],'C','Two-rescuer bag-mask use is more effective: one rescuer holds a tight seal with both hands (E-C clamp) while the other squeezes the bag.',AHA_BLS),
  q(ADV,'Which advanced airway is placed blindly, above the vocal cords, without seeing the cords directly?','A supraglottic airway',['An endotracheal tube','A nasal cannula only','A tracheostomy tube'],'D','Supraglottic airways such as the laryngeal mask or i-gel sit above the glottis and are inserted without visualizing the vocal cords.',AHA_BLS),
  q(RB,'During rescue breathing for an adult who has a pulse, how often should the rescuer recheck the pulse?','About every 2 minutes',['After every breath','Only once at the start','Every 10 minutes'],'A','Reassess the pulse about every 2 minutes; if it is lost, start CPR beginning with compressions.',AHA_BLS),
  q(RB,'The first rescue breath does not make the chest rise. What should the rescuer do next?','Retilt the head, reseal and try again',['Blow harder and faster until it rises','Skip breaths and stop the attempt','Give abdominal thrusts right away'],'B','If the chest does not rise, the airway may not be open; retilt the head and reseal before giving the second breath.',ARC_BLS),
  q(CH,'Where does a rescuer place the fist for abdominal thrusts on a conscious choking adult?','Just above the navel, well below the breastbone',['Directly on the lower tip of the breastbone','Over the left side of the lower ribs','Below the navel, near the hips'],'C','The fist goes just above the navel and well below the breastbone, pressing in and up with quick thrusts.',AHA_FA),
  q(CH,'Should a rescuer do a blind finger sweep in a choking person’s mouth?','No; remove an object only if it can be seen',['Yes; always sweep before any thrust','Yes; but only in infants and toddlers who are choking','No; never look in the mouth at all'],'D','Blind sweeps can push the object deeper; remove it only if you can see it and easily reach it.',AHA_BLS),
  q(BASIC,'In the SAMPLE history, what does the “S” stand for?','Signs and symptoms',['Skin color and temperature','Severity of injury','Scene safety'],'A','SAMPLE stands for signs and symptoms, allergies, medications, pertinent history, last oral intake and events leading up.',ARC_FA),
  q(BASIC,'A 10-year-old is injured at a park, and a parent is present. Whose consent is needed for first aid?','The parent or guardian’s consent',['The child’s consent only','No consent is ever needed','A police officer’s written consent'],'B','A minor cannot legally give consent, so ask the parent or guardian; if none is present in an emergency, consent is implied.',AHA_FA),
  q(BASIC,'When soap and water are not available, what kind of hand sanitizer should be used?','An alcohol-based rub with at least 60% alcohol',['Any lotion that contains a pleasant scent','A sanitizer with less than 20% alcohol','Plain water with no soap at all'],'C','Alcohol-based hand rubs with at least 60% alcohol work when hands are not visibly dirty; wash with soap and water as soon as possible.',AHA_FA),
  q(BASIC,'What is a normal resting pulse rate for an adult?','60–100 beats per minute',['20–40 beats per minute','120–160 beats per minute','40–50 beats per minute'],'D','A normal adult resting pulse is 60–100 beats per minute; above 100 is tachycardia and below 60 is bradycardia.',DHO),
  q(BASIC,'A first aider with a duty to act gives care far below the expected standard, and the person is harmed. What is this called?','Negligence',['Abandonment','Implied consent','Confidentiality'],'A','Negligence is failing to give reasonable care as a trained person would, causing injury; abandonment is leaving a person without handing off care.',ARC_FA),
  q(BASIC,'An unresponsive person must be moved quickly from a burning car, with no time to stabilize. Which move is used?','A clothes drag, pulling along the body’s long axis',['A two-person seat carry with a chair','A firefighter’s carry over the shoulder only','Lifting by the arms and legs from the sides'],'B','A clothes drag pulls the person by the shirt behind the neck, supporting the head and keeping the spine as straight as possible.',ARC_FA),
  q(BASIC,'During a check for injuries, why should a first aider look for a medical ID bracelet or necklace?','It can reveal conditions such as diabetes or allergies',['It shows the person’s home address for police','It must be removed before any first aid can begin','It replaces the need to ask for consent'],'C','Medical ID jewelry lists conditions such as diabetes, epilepsy or severe allergies that can guide first aid.',AHA_FA),
  q(MED,'In B.E. F.A.S.T. for stroke, what does the first “B” stand for?','Balance',['Breathing','Bleeding','Blood sugar'],'D','B.E. F.A.S.T.: balance, eyes, face drooping, arm weakness, speech difficulty and time to call 911.',AHA_FA),
  q(MED,'Which finding best shows that an allergic reaction has become anaphylaxis?','Hives with throat tightness and trouble breathing',['A few itchy bumps on one arm only','Sneezing and a runny nose in spring','A mild rash on the chest that fades within an hour'],'A','Anaphylaxis is a severe reaction involving the airway, breathing or circulation, such as throat swelling, wheezing or low blood pressure.',AHA_FA),
  q(MED,'A child has brief spells of staring, with no response for a few seconds, then resumes activity. What type of seizure is this?','An absence seizure',['A febrile seizure','A tonic-clonic seizure','Status epilepticus'],'B','Absence seizures cause brief staring spells; the child should be reported to a provider, but no special first aid is needed during them.',DHO),
  q(MED,'Besides the chest, where else may heart attack pain or discomfort spread?','Arms, back, neck, jaw or stomach',['Only the lower legs and feet','Only the forehead and scalp','Only the hands and fingertips'],'C','Heart attack discomfort can spread to one or both arms, the back, neck, jaw or stomach, sometimes with shortness of breath or sweating.',AHA_FA),
  q(MED,'A toddler swallowed a household cleaner. What should the first aider avoid doing?','Making the child vomit',['Calling Poison Control','Checking the product label','Watching the child’s breathing'],'D','Inducing vomiting can cause more injury; call Poison Control (or 911 if the child is very ill) and follow their advice.',AHA_FA),
  q(MED,'A person with asthma has trouble breathing. Which sound often accompanies narrowed airways?','Wheezing, a high-pitched whistling',['Gurgling from fluid in the stomach','Clicking in the jaw while chewing','Crackling under the skin of the neck'],'A','Asthma narrows and inflames the airways, causing wheezing, coughing, chest tightness and shortness of breath.',AHA_FA),
  q(MED,'A person who drank heavily is drowsy but breathing normally. What is the best first aid?','Place them in the recovery position and stay with them',['Give strong coffee to wake them up quickly','Put them in a cold shower to sober them','Let them sleep it off alone, lying flat on their back'],'B','Alcohol can cause vomiting and slowed breathing; the recovery position protects the airway, and someone should stay and watch breathing.',ARC_FA),
  q(MED,'A person who fainted wakes up on the floor within a minute. What is the best next step?','Keep them lying down for several minutes before slowly sitting up',['Have them stand up and walk right away','Give them a large meal immediately so blood sugar rises fast','Splash cold water on their face repeatedly'],'C','After fainting, the person should rest lying down and rise slowly; call 911 if they do not recover quickly or have other warning signs.',AHA_FA),
  q(MED,'When giving an epinephrine auto-injector, how long is it typically held in place against the thigh?','About 3 seconds, as the device instructions direct',['About 1 minute, to be safe, then massage the site','It is pulled out at once','About 30 seconds, then repeated'],'D','Most auto-injectors are pressed into the outer thigh and held for about 3 seconds so the full dose is delivered; follow the device’s instructions.',AHA_FA),
  q(INJ,'In RICE care for a sprained ankle, what does the “E” stand for?','Elevation',['Exercise','Evaluation','Ending'],'A','RICE means rest, ice, compression and elevation; raising the limb helps reduce swelling.',DHO),
  q(INJ,'What is a sprain?','A stretched or torn ligament at a joint',['A broken bone that pierces the skin','A bruise under the surface of the skin','A muscle cramp after hard exercise'],'B','A sprain injures ligaments, which connect bones at a joint; a strain injures a muscle or tendon.',DHO),
  q(INJ,'A broken bone pokes through the skin of the forearm. What should the first aider do?','Cover the wound and splint without pushing the bone back',['Push the bone back under the skin first','Pull the arm straight to realign the bone before splinting','Leave it exposed so it can drain freely'],'C','For an open fracture, control bleeding, cover the wound with a sterile dressing and splint as found; never push the bone back in.',AHA_FA),
  q(INJ,'A worker gets dust in the eye. What is the best first aid?','Flush the eye gently with clean water',['Rub the eye to work the dust out','Remove it with a cotton swab tip','Cover the eye and ignore it for a day'],'D','Gently flushing with clean water usually removes small particles; rubbing can scratch the cornea, and anything stuck needs medical care.',AHA_FA),
  q(INJ,'A child scrapes a knee on pavement, wearing away the top layers of skin. What type of wound is this?','An abrasion',['An avulsion','A puncture','An amputation'],'A','An abrasion scrapes away the outer skin; clean it well with running water to remove dirt and cover it with a dressing.',DHO),
  q(INJ,'Where should a tourniquet first be placed on a bleeding arm?','About 2–3 inches above the wound, not over a joint',['Directly over the wound itself','Below the wound, nearer the hand','Around the joint closest to the wound, such as the elbow'],'B','A tourniquet is placed 2–3 inches above the wound, between the wound and the heart, avoiding joints, then tightened until bleeding stops.',AHA_FA),
  q(INJ,'After a fall, a person has abdominal bruising, a rigid belly and is vomiting material like coffee grounds. What is suspected?','Internal bleeding',['A simple stomach ache','A mild food allergy','A pulled back muscle'],'C','Signs of internal bleeding include bruising, a tender or rigid abdomen, vomiting or coughing blood and shock; call 911.',AHA_FA),
  q(INJ,'A person’s shoulder looks deformed after a fall, and a dislocation is suspected. What should the first aider do?','Support it as found and get medical care, without trying to put it back',['Pull firmly on the arm to snap it back','Have the person swing the arm in circles to loosen the joint and reset it','Wrap it tightly against the head to hold it'],'D','Trying to put a dislocated joint back can damage nerves and vessels; support the limb in a comfortable position and seek care.',ARC_FA),
  q(INJ,'A small wooden splinter is in a finger, and the end is visible. What is the best first aid?','Wash the area, then pull it out with clean tweezers',['Leave it in to work out over a few weeks','Cut the skin deeply with a knife to reach it','Push it in further so it will dissolve'],'A','Clean the area, remove the splinter with clean tweezers along the angle it entered, wash again and cover; seek care if it is deep.',ARC_FA),
  q(ENV,'Under the 30-30 lightning rule, how long should people wait after the last thunder before going back outside?','30 minutes',['5 minutes','10 minutes','2 hours'],'B','Lightning can strike miles from a storm, so stay sheltered until 30 minutes after the last thunder is heard.',ARC_FA),
  q(ENV,'Which action is correct first aid for a venomous snakebite?','Keep the person still and calm, and call 911',['Cut the wound and suck out the venom','Apply a tight tourniquet above the bite','Pack the bite with ice for an hour'],'C','Keep the person still with the bitten limb at rest; do not cut, suck, ice or apply a tourniquet. Get emergency care.',AHA_FA),
  q(ENV,'A painless spider bite becomes an open sore with dying tissue over several days. Which spider is most likely?','Brown recluse',['Black widow','Daddy longlegs','Wolf spider'],'D','Brown recluse venom destroys tissue and can form a slowly spreading ulcer; black widow venom mainly causes muscle pain and cramping.',AHA_FA),
  q(ENV,'A person with hypothermia stops shivering and becomes confused and sleepy. What does this suggest?','Hypothermia is becoming severe',['The person is rewarming normally','The person has heat exhaustion','The danger has completely passed'],'A','Loss of shivering with confusion signals worsening hypothermia; handle gently, warm the person and call 911.',AHA_FA),
  q(ENV,'Someone is struggling in water a few feet from a dock. What is the safest way for an untrained bystander to help?','Reach or throw something that floats, without going in',['Jump in and swim out to carry them back to the dock','Wait until they stop moving, then go in','Walk in and grab them around the neck'],'B','“Reach or throw, don’t go”: a panicking swimmer can pull a rescuer under, so use a pole, rope or floating object from shore.',ARC_FA)
 ],9501)
};
